def gen(rng):
    def fmt(a, qs):
        return f'{len(a)} {len(qs)}\n' + ' '.join(map(str, a)) + '\n' + ' '.join(map(str, qs))

    tests = [
        fmt([1], [1]), fmt([1], [10**9]), fmt([10**9], [1]),
        fmt([4, 1, 7, 10], [2, 6, 12]), fmt([5, 5, 5], [5, 1]),
        fmt([3, 1, 2], [1, 2, 3, 4]),
        fmt([10**9] * 6, [1, 10**9]),
    ]
    for n, q in [(2, 2), (3, 5), (5, 5), (8, 4), (10, 10), (15, 8), (20, 20)]:
        for _ in range(2):
            hi = rng.choice([5, 20, 100, 10**9])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)], [rng.randint(1, hi) for _ in range(q)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], [rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 10**6) for _ in range(N)], [rng.randint(1, 10**6) for _ in range(N)]))
    tests.append(fmt([10**9] * N, [1] * N))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], [10**9 if i % 2 else 1 for i in range(N)]))
    return tests

